import AppKit
import Foundation

/// Decides which clipboard contents must never be saved to history.
enum SensitiveContent {
    /// Markers defined at nspasteboard.org and used by password managers.
    static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword"
    ]

    static let defaultExcludedBundleIDs: [String] = [
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.bitwarden.desktop",
        "com.apple.keychainaccess",
        "com.apple.Passwords",
        "com.lastpass.LastPass",
        "com.dashlane.Dashlane",
        "com.dashlane.dashlanephonefinal"
    ]

    private static let patterns: [NSRegularExpression] = [
        #"sk-ant-[A-Za-z0-9_\-]{10,}"#,                       // Anthropic
        #"\bsk-[A-Za-z0-9_\-]{20,}"#,                          // OpenAI and similar
        #"\bAKIA[0-9A-Z]{16}\b"#,                              // AWS access key id
        #"\bgh[pousr]_[A-Za-z0-9]{36,}\b"#,                    // GitHub tokens
        #"\bgithub_pat_[A-Za-z0-9_]{40,}\b"#,
        #"\bxox[abprs]-[A-Za-z0-9\-]{10,}"#,                   // Slack
        #"\bAIza[0-9A-Za-z_\-]{35}\b"#,                        // Google API key
        #"\b(sk|rk)_live_[0-9A-Za-z]{20,}"#,                   // Stripe live keys
        #"-----BEGIN [A-Z ]*PRIVATE KEY-----"#,                // PEM private keys
        #"\beyJ[A-Za-z0-9_\-]{10,}\.eyJ[A-Za-z0-9_\-]{10,}\.[A-Za-z0-9_\-]{10,}"# // JWT
    ].compactMap { try? NSRegularExpression(pattern: $0) }

    private static let cardCandidate = try? NSRegularExpression(pattern: #"\b(?:\d[ \-]?){12,18}\d\b"#)

    static func hasSkipMarker(_ types: [String]) -> Bool {
        types.contains { skipTypes.contains($0) }
    }

    /// API keys, tokens, private keys or a card number that passes the Luhn check.
    static func looksSensitive(_ text: String) -> Bool {
        let sample = String(text.prefix(20_000))
        let range = NSRange(sample.startIndex..., in: sample)
        if patterns.contains(where: { $0.firstMatch(in: sample, range: range) != nil }) { return true }
        guard let cardCandidate else { return false }
        for match in cardCandidate.matches(in: sample, range: range) {
            guard let swiftRange = Range(match.range, in: sample) else { continue }
            let digits = sample[swiftRange].filter(\.isNumber)
            if (13...19).contains(digits.count) && luhn(String(digits)) { return true }
        }
        return false
    }

    static func luhn(_ digits: String) -> Bool {
        let values = digits.compactMap(\.wholeNumberValue)
        guard values.count == digits.count, values.count >= 12 else { return false }
        var sum = 0
        for (index, value) in values.reversed().enumerated() {
            if index % 2 == 1 {
                let doubled = value * 2
                sum += doubled > 9 ? doubled - 9 : doubled
            } else {
                sum += value
            }
        }
        return sum % 10 == 0
    }
}
